function addTaskCard(jobId,wfName){if(tasks.has(jobId))return tasks.get(jobId);const list=document.getElementById('taskList'),card=document.createElement('div'),spin=document.createElement('div'),info=document.createElement('div'),name=document.createElement('div'),meta=document.createElement('div'),time=document.createElement('div'),view=document.createElement('button');card.className='task-card';spin.className='task-spin';info.className='task-info';name.className='task-name';name.textContent=wfName;meta.className='task-meta';meta.setAttribute('aria-live','polite');time.className='task-time';time.textContent='00:00';view.className='task-view';view.type='button';view.textContent='查看结果';view.hidden=true;info.append(name,meta);card.append(spin,info,time,view);list.prepend(card);const t={card,timeEl:time,metaEl:meta,spinEl:spin,viewEl:view,timer:null,startTs:Date.now(),wfName,pollFailures:0};tasks.set(jobId,t);t.timer=setInterval(()=>{t.timeEl.textContent=fmtTime((Date.now()-t.startTs)/1000)},500);refreshTaskCount();return t}
function removeTaskCard(jobId){const t=tasks.get(jobId);if(!t)return;if(t.timer)clearInterval(t.timer);t.card.remove();tasks.delete(jobId);refreshTaskCount()}
function renderTaskResult(j){registerGalleryJob(j)}
async function pollTask(jobId){const t=tasks.get(jobId);if(!t)return;try{const j=await api('/api/job/'+jobId);if(!tasks.has(jobId))return;t.pollFailures=0;t.metaEl.textContent=taskStatusText(j)+' · '+videoCoinText(j);t.spinEl.className='task-spin '+taskStatusClass(j);if(j.status==='done'){if(t.timer){clearInterval(t.timer);t.timer=null}t.timeEl.textContent=fmtTime(j.elapsed||0);renderTaskResult(j);t.viewEl.hidden=!(j.images&&j.images.length);t.viewEl.onclick=()=>{registerGalleryJob(j);document.getElementById('mediaGallery').scrollIntoView({block:'nearest'})};return}if(j.status==='error'){if(t.timer){clearInterval(t.timer);t.timer=null}t.timeEl.textContent='—';t.metaEl.textContent='✗ '+(j.error||'生成失败');return}setTimeout(()=>pollTask(jobId),5000)}catch(error){if(!tasks.has(jobId))return;t.pollFailures++;if(t.pollFailures>=6){if(t.timer){clearInterval(t.timer);t.timer=null}t.spinEl.className='task-spin err';t.timeEl.textContent='—';t.metaEl.textContent='暂时无法获取状态，刷新页面可恢复';return}t.metaEl.textContent='状态连接中断，正在重试 '+t.pollFailures+'/6';setTimeout(()=>pollTask(jobId),Math.min(12000,4000+t.pollFailures*1500))}}
async function generate(){if(genRunning)return;if(!cur)return;const workflow=cur,state=ensureMediaState(workflow.id);if(Object.values(state.uploading).some(Boolean)){document.getElementById('genStatus').textContent='素材仍在上传，请完成后再生成';return}genRunning=true;const btn=document.getElementById('genBtn');btn.disabled=true;btn.classList.add('is-loading');const st=document.getElementById('genStatus');st.textContent='正在提交…';document.getElementById('genResult').innerHTML='';let pending={};try{pending=JSON.parse(localStorage.getItem(pendingVideoSubmitKey)||'{}')}catch{}const client_request_id=pending.workflow===workflow.id&&pending.id?pending.id:'video-'+Date.now()+'-'+Math.random().toString(36).slice(2);localStorage.setItem(pendingVideoSubmitKey,JSON.stringify({workflow:workflow.id,id:client_request_id}));try{const prompt=(document.getElementById('param_prompt')?.value||'').trim();if(!prompt)throw new Error('提示词不能为空');const required=Object.entries(workflow.rh_media||{}).filter(([,m])=>m.required).map(([k])=>k);const missing=required.filter(k=>!state.tokens[k]);if(missing.length)throw new Error('缺少必传素材：'+missing.join(', '));const body={workflow:workflow.id,prompt:prompt,negative_prompt:(document.getElementById('param_negative')?.value||'').trim(),media:{...state.tokens},params:collectParams(),client_request_id};const r=await api('/api/video-generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});localStorage.removeItem(pendingVideoSubmitKey);if(!r.job_id)throw new Error(r.error||'提交失败');addTaskCard(r.job_id,workflow.name);st.textContent='✓ 已提交，任务 '+r.job_id+' 在下方队列中';pollTask(r.job_id)}catch(e){const definitiveRejection=e.status>=400&&e.status<500;if(definitiveRejection)localStorage.removeItem(pendingVideoSubmitKey);st.textContent='✗ '+e.message+(definitiveRejection?'':'；网络不明时再次点击会复用请求号')}finally{genRunning=false;btn.classList.remove('is-loading');btn.disabled=false}}
async function history(){const l=document.getElementById('histList');l.textContent='加载中…';const a=await api('/api/jobs?scope=video');l.replaceChildren();a.filter(j=>j.workflow&&WFS.find(w=>w.id===j.workflow)).slice(0,10).forEach(j=>{const w=WFS.find(x=>x.id===j.workflow),d=document.createElement('div'),title=document.createElement('b'),note=document.createElement('div'),button=document.createElement('button');d.className='job';title.textContent=w?w.name:'视频';note.className='note';note.textContent=j.status+' · '+videoCoinText(j)+' · '+(j.elapsed||'')+'秒';button.className='dl';button.textContent='查看结果';button.onclick=()=>{addResult(j);histOverlay.classList.remove('open')};d.append(title,note,button);l.appendChild(d)})}
